class Book:
    def __init__(self, title, pages):
        self.title = title
        self.pages = pages
    def __str__(self):
        return f'{self.title}'    # print(book)
    def __repr__(self):
        return f'Book({self.title!r})'  # repr(book)
    def __len__(self):
        return self.pages          # len(book)
    def __eq__(self, other):
        return self.title == other.title

class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def radius(self):
        return self._radius

    @radius.setter
    def radius(self, value):
        if value < 0:
            raise ValueError('Radius must be positive')
        self._radius = value

    @property
    def area(self):
        return 3.14159 * self._radius ** 2

c = Circle(5)
print(c.radius)  # 5  — как атрибут, не метод
c.radius = 10

class MathHelper:
    multiplier = 2

    @staticmethod
    def add(a, b):       # Нет self, нет cls — просто функция
        return a + b

    @classmethod
    def double(cls, x):  # cls — ссылка на класс, не на объект
        return x * cls.multiplier

MathHelper.add(3, 4)     # 7
MathHelper.double(5)     # 10

from dataclasses import dataclass, field

@dataclass
class Product:
    name: str
    price: float
    tags: list = field(default_factory=list)

# __init__, __repr__, __eq__ созданы автоматически
p = Product('Coffee', 5.99)
print(p)  # Product(name='Coffee', price=5.99, tags=[])

@dataclass(frozen=True)  # неизменяемый
class Point:
    x: float
    y: float

from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self) -> float:   # Обязательно переопределить
        pass

    @abstractmethod
    def perimeter(self) -> float:
        pass

class Circle(Shape):
    def __init__(self, r):
        self.r = r
    def area(self):
        return 3.14 * self.r ** 2
    def perimeter(self):
        return 2 * 3.14 * self.r

# Shape()  # TypeError: Can't instantiate abstract class

class Countdown:
    def __init__(self, start):
        self.current = start

    def __iter__(self):       # делает объект итерируемым
        return self

    def __next__(self):       # вызывается на каждом шаге for
        if self.current <= 0:
            raise StopIteration  # сигнал конца итерации
        val = self.current
        self.current -= 1
        return val

for n in Countdown(3):
    print(n)  # 3 2 1

# Короткий способ: генераторная функция (yield)
def countdown(n):
    while n > 0:
        yield n
        n -= 1

class ManagedFile:
    def __init__(self, path):
        self.path = path

    def __enter__(self):          # вход в with-блок
        self.file = open(self.path)
        return self.file

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.file.close()         # вызывается ВСЕГДА (даже при исключении)
        return False              # не подавлять исключения

with ManagedFile('data.txt') as f:
    content = f.read()

# Короткий способ через декоратор
from contextlib import contextmanager

@contextmanager
def managed_file(path):
    f = open(path)
    try:
        yield f
    finally:
        f.close()
